// Polski – aus de.js übersetzt (15.10.2026). Ladensprache, kurz. / Język z lokalu: krótkie zdania, na „ty”, bez urzędowych słów.
// Słowniczek: Wareneinsatz = koszt towaru · bleibt dir pro Stück = zostaje ci na sztuce · Müll = śmieci (Tonne = kosz) · Kühlstelle = punkt chłodzenia
// Rundgang = obchód · Inventur = inwentaryzacja · Putzplan = plan sprzątania · Beleg = rachunek · Umsatz = utarg · Zähler = licznik
// Einrichtung = konfiguracja · Laden = lokal · Gericht = danie · Rezept = przepis · Speisekarte = karta dań · Personalessen = posiłek pracowniczy
// Liczba mnoga: 1 / 2–4 (bez 12–14) / 5+
const lm = (n, a, b, c) => { const x = Math.abs(Number(n)); if (!Number.isFinite(x)) return c; if (!Number.isInteger(x)) return b; const d = x % 10, h = x % 100; return x === 1 ? a : d >= 2 && d <= 4 && (h < 12 || h > 14) ? b : c; };

